/** 이 공격이 일으키는 트리거. 없으면 빈 배열. */
export const triggersOf = (attackId: string): AttackTrigger[] => ATTACK_TRIGGERS[attackId] ?? [];

/** 트리거가 걸린 공격 수. 진행 상황을 세는 데 쓴다. */
export const triggerAttackCount = (): number => Object.keys(ATTACK_TRIGGERS).length;

/**
 * 카드에 한 줄로 띄울 말. 「서리 1스택 추가」 · 「암흑 소모」 · 「기(炁) 50pt 획득」.
 *
 * 이상 효과는 스택, 자원은 pt로 세는 것이 게임 표기라 단위를 갈라 쓴다.
 */
export function triggerLabel(trigger: AttackTrigger): string {
  const stacked = trigger.action === "add" ? "추가" : "소모";
  if (trigger.anomaly) {
    const name = ANOMALIES[trigger.anomaly].name;
    return trigger.amount === undefined
      ? `${name} ${stacked}`
      : `${name} ${trigger.amount}스택 ${stacked}`;
  }
  // 적에게 거는 상태는 「부여 / 제거」가 게임 말투에 맞는다.
  if (trigger.status) {
    const verb = trigger.action === "add" ? "부여" : "제거";
    return trigger.amount === undefined
      ? `${trigger.status} ${verb}`
      : `${trigger.status} ${trigger.amount}스택 ${verb}`;
  }
  const name = trigger.resource ?? "자원";
  const gain = trigger.action === "add" ? "획득" : "소모";
  return trigger.amount === undefined ? `${name} ${gain}` : `${name} ${trigger.amount}pt ${gain}`;
}

/** 이 트리거가 어느 갈래인지. 화면에서 색을 가르는 데 쓴다. */
export const triggerKind = (t: AttackTrigger): "anomaly" | "status" | "resource" =>
  t.anomaly ? "anomaly" : t.status ? "status" : "resource";
